<?php $cards=[['label'=>'Vendas no mês','value'=>'R$ '.number_format((float)($stats['month_sales']??0),2,',','.')],['label'=>'Pedidos pendentes','value'=>(int)($stats['pending_orders']??0)],['label'=>'Produtos','value'=>(int)($stats['products']??0)],['label'=>'Avaliação','value'=>'—']]; ?><div class="stat-grid"><?php foreach($cards as $stat) require dirname(__DIR__).'/components/dashboard/stat-card.php'; ?></div><?php $maxChart=max(1,...array_map(static fn($point)=>(float)$point['value'],$chart));?><div class="dashboard-columns"><section class="panel"><div class="panel-head"><div><small>DESEMPENHO</small><h3>Vendas dos últimos 14 dias</h3></div><span class="chart-total"><?=array_sum(array_column($chart,'orders'))?> pedidos</span></div><div class="metric-chart" role="img" aria-label="Vendas diárias reais da loja nos últimos 14 dias"><?php foreach($chart as $point):?><div class="metric-chart__column" title="<?=e($point['label'])?> · R$ <?=number_format((float)$point['value'],2,',','.')?> · <?=(int)$point['orders']?> pedido(s)"><span>R$ <?=number_format((float)$point['value'],0,',','.')?></span><i style="height:<?=max(3,round(((float)$point['value']/$maxChart)*100,1))?>%"></i><small><?=e($point['label'])?></small></div><?php endforeach;?></div></section><section class="panel"><div class="panel-head"><div><small>ATENÇÃO</small><h3>Próximas ações</h3></div></div><ul class="action-list"><li><span>01</span>Revise os pedidos pagos</li><li><span>02</span>Mantenha estoque e catálogo atualizados</li><li><span>03</span>Confirme a origem dos envios</li></ul></section></div>
